import { ref, watch, watchEffect } from 'vue'

const id = ref(1)

// watch: id が変わった瞬間だけ走る。初期実行はしない（immediate: true で出来る）
watch(id, async (newId, oldId) => {
  console.log(`changed: ${oldId} -> ${newId}`)
  await fetchUser(newId)
})

// watchEffect: 即時実行 + cb 内で読んだ ref を自動追跡
watchEffect(async () => {
  await fetchUser(id.value) // id.value を読んだので id の変化に反応する
})

